/**
 * Tratamentos CPT para seed (Viscos + Ozônio).
 *
 * @return list<array{slug:string,title:string,excerpt:string,content:string,eyebrow:string,lead:string,faqs:list<array{question:string,answer:string}>,image:string}>
 */
function idc_default_tratamentos_seed(): array {
	$orto = idc_default_ortopedia_treatments();
	$out  = [];
	$map  = [
		'Viscossuplementação' => [
			'slug'  => 'viscosuplementacao',
			'image' => 'assets/images/pages/hub-ortopedia.jpg',
		],
		'Ozonioterapia' => [
			'slug'  => 'ozonioterapia',
			'image' => 'assets/images/pages/hub-ortopedia.jpg',
		],
	];

	foreach ($orto as $card) {
		$title = (string) ($card['title'] ?? '');
		if ($title === '' || !isset($map[$title])) {
			continue;
		}
		$meta = $map[$title];
		$out[] = [
			'slug'    => $meta['slug'],
			'title'   => $title,
			'excerpt' => (string) ($card['intro'] ?? ''),
			'content' => '<p>' . (string) ($card['intro'] ?? '') . '</p><p>A indicação, o protocolo e o número de sessões são definidos após avaliação ortopédica individualizada no Instituto Dr. Chao.</p>',
			'eyebrow' => 'TRATAMENTO · ORTOPEDIA REGENERATIVA',
			'lead'    => (string) ($card['intro'] ?? ''),
			'faqs'    => is_array($card['faqs'] ?? null) ? $card['faqs'] : [],
			'image'   => $meta['image'],
		];
	}

	return $out;
}
